1	/* ===== Bộ điều khiển chế độ Trực tiếp / Mô phỏng (D-043, spec §4.4) =====
2	   Một chỗ duy nhất ghi số liệu thật vào cảnh. Trực tiếp: mỗi khung đặt dayNight.target theo độ cao mặt trời thật (solar.ts) và giữ `sun` cho applyNight;
3	   kho số liệu (store.ts) báo đổi thì tính đích thời tiết (envMap.ts) rồi weather.setLive(). Mô phỏng: không ghi gì (preset / cường độ / đêm của người xem giữ nguyên).
4	   Không import three / DOM: mọi phụ thuộc tiêm vào để chạy dưới Node (tests/live-unit/liveEnv.test.ts). Không cấp phát mỗi khung. */
5	import type { CONFIG } from '../config';
6	import type { WeatherParams } from '../environment/weather/state';
7	import type { EnvStore } from './store';
8	import { envToParams } from './envMap';
9	import { sunPosition, liveNight, sunWarm } from './solar';
10	
11	export type EnvMode = 'live' | 'manual';
12	export type LiveSun = { elev: number; azim: number; warm: number };   // cùng dạng SunOverride của core/dayNight.ts (không import để giữ module thuần)
13	export type LiveDeps = {
14	  cfg: typeof CONFIG.live; lat: number; lon: number;
15	  refreshMs: number;                                              // CONFIG.env.refreshMs: số liệu cũ hơn mức này thì làm mới khi vào Trực tiếp
16	  now: () => number;                                              // epoch ms (đã hiệu chỉnh: giờ máy + store.skew())
17	  store: Pick<EnvStore, 'data' | 'status' | 'onChange' | 'refresh'>;
18	  weather: { setLive(p: WeatherParams | null, instant?: boolean): void; stopScenario(): void; standTrees(): void };
19	  dayNight: { night: number; target: number };
20	  initial: EnvMode;
21	};
22	export type LiveEnv = {
23	  readonly mode: EnvMode; readonly sun: LiveSun | null;          // sun: null ở Mô phỏng ⇒ main.ts gọi applyNight như cũ
24	  setMode(m: EnvMode, why?: 'user' | 'feature'): void;            // 'feature': tính năng cần đêm tự chuyển sang Mô phỏng (giao diện hiện thông báo)
25	  update(dt: number): void;                                       // gọi mỗi khung TRƯỚC stepNight
26	  onChange(fn: (why: 'user' | 'feature' | 'data') => void): void;
27	};
28	
29	/** Thời gian chờ tới lần lấy số liệu kế tiếp ở Trực tiếp: mốc quan trắc obsStepMs kế tiếp (theo UTC) + obsDelayMs + nhiễu 0–jitterMs, không dưới minDelayMs.
30	    Mọi máy căn cùng mốc nên đổi số liệu gần như cùng lúc (spec §4.5). rnd: bộ sinh riêng rng(seed), không dùng rand(). */
31	export function liveNextDelay(now: number, cfg: { obsStepMs: number; obsDelayMs: number; jitterMs: number; minDelayMs: number }, rnd: () => number): number {
32	  const S = cfg.obsStepMs, at = (Math.floor((now - cfg.obsDelayMs) / S) + 1) * S + cfg.obsDelayMs;
33	  return Math.max(cfg.minDelayMs, at - now + rnd() * cfg.jitterMs);
34	}
35	
36	export function createLiveEnv(d: LiveDeps): LiveEnv {
37	  const cfg = d.cfg;
38	  let mode: EnvMode = d.initial;
39	  const sunObj: LiveSun = { elev: 0, azim: 180, warm: 0 };       // một đối tượng dùng lại (không cấp phát mỗi khung)
40	  let sun: LiveSun | null = null;
41	  let sunAt = -Infinity;                    // giờ (ms) của lần tính mặt trời gần nhất: tính lại khi lệch > 1 s (mặt trời đi 0,004°/s)
42	  let firstNight = mode === 'live';         // lần update đầu ở Trực tiếp lúc mở trang: gán luôn night = target (không chuyển cảnh)
43	  let applied = false;                      // đã áp số liệu lần nào chưa: lần đầu ở Trực tiếp lúc mở trang áp tức thì
44	  let lastData: unknown = null, lastUp: boolean | null = null;   // số liệu / ngày–đêm của lần setLive gần nhất (kho báo lỗi mà data giữ nguyên ⇒ không gọi lại)
45	  let manualTarget = d.dayNight.target;     // đêm đích của Mô phỏng, nhớ lúc rời Mô phỏng
46	  const subs: Array<(why: 'user' | 'feature' | 'data') => void> = [];
47	  const emit = (why: 'user' | 'feature' | 'data') => { for (const f of subs) { try { f(why); } catch (e) { console.error(e); } } };
48	
49	  const calcSun = (force: boolean) => {
50	    const t = d.now();
51	    if (!force && Math.abs(t - sunAt) <= 1000) return;
52	    sunAt = t;
53	    const p = sunPosition(t, d.lat, d.lon);
54	    sunObj.elev = p.elev; sunObj.azim = p.azim; sunObj.warm = sunWarm(p.elev, cfg.warm);
55	    sun = sunObj;
56	  };
57	  /* Số liệu → đích thời tiết. Chỉ ở Trực tiếp; data null (đang tải / mất mạng không đệm) ⇒ không gọi gì, giữ trạng thái cuối */
58	  const applyData = (instant: boolean) => {
59	    const data = d.store.data;
60	    if (mode !== 'live' || !data) return;
61	    const up = sunObj.elev > 0;
62	    if (data === lastData && up === lastUp) return;
63	    lastData = data; lastUp = up;
64	    d.weather.setLive(envToParams(data, up, cfg), instant);
65	    applied = true;
66	    emit('data');
67	  };
68	
69	  d.store.onChange(() => { if (mode === 'live') applyData(!applied); });
70	  if (mode === 'live') { calcSun(true); applyData(true); }       // kho có thể đã có số liệu (bộ nhớ đệm) trước khi bộ điều khiển được tạo
71	
72	  return {
73	    get mode() { return mode; },
74	    get sun() { return mode === 'live' ? sun : null; },
75	    setMode(m: EnvMode, why: 'user' | 'feature' = 'user') {
76	      if (m === mode) return;
77	      if (m === 'manual') {
78	        mode = 'manual'; firstNight = false;
79	        d.weather.setLive(null);
80	        d.dayNight.target = manualTarget;
81	        sun = null;
82	      } else {
83	        manualTarget = d.dayNight.target;
84	        mode = 'live'; firstNight = false; applied = true;   // từ Mô phỏng: cảnh tiến dần tới trạng thái thật (không tức thì)
85	        d.weather.stopScenario(); d.weather.standTrees();
86	        const data = d.store.data;
87	        if (!data || d.now() - data.obs > d.refreshMs) void d.store.refresh();
88	        calcSun(true);
89	        d.dayNight.target = liveNight(sunObj.elev, cfg);
90	        lastData = null; lastUp = null;
91	        applyData(false);
92	      }
93	      emit(why);
94	    },
95	    update(_dt: number) {
96	      // Không dùng dt: đêm tiến dần bằng stepNight, thời tiết bằng stepWeather (cả hai nhận dt đã kẹp trong animate); sau tab ẩn lâu đích đổi một lần rồi cảnh tiến dần
97	      if (mode !== 'live') return;
98	      calcSun(false);
99	      d.dayNight.target = liveNight(sunObj.elev, cfg);
100	      if (firstNight) { d.dayNight.night = d.dayNight.target; firstNight = false; }
101	      if (lastData && (sunObj.elev > 0) !== lastUp) applyData(false);   // qua chân trời: mù nóng chỉ ban ngày (envToParams sunUp)
102	    },
103	    onChange(fn) { subs.push(fn); }
104	  };
105	}
