7	
8	/* ===== Giờ + thời tiết thực tế tại Đà Nẵng (D-042) =====
9	   Chỉ báo #envPill luôn hiện + thẻ #envCard (tờ 'env' của compactUI.ts). Đồng hồ chạy mỗi giây theo CONFIG.env.tz, số liệu từ realtime/store.ts.
10	   Chỉ hiển thị: không đọc / ghi thời tiết mô phỏng, thanh Ngày / Đêm hay đèn. Chỉ ghi DOM khi chuỗi đổi (đồng hồ mỗi giây không gây bố trí lại thừa). */
11	
12	export type EnvUI = { store: EnvStore; render(): void; setNow(fn: (() => number) | null): void; now(): number };   // now(): giờ đã hiệu chỉnh (giờ máy / setNow + store.skew(), D-043)
13	
14	/* Biểu tượng nét 24×24 (chép từ prototype; 'cloud', 'fog', 'storm', 'snow' vẽ thêm cùng nét); 'off' = mất kết nối */
15	const RAIN_CLOUD = '<path d="M7 15.5h10a3.8 3.8 0 0 0 .5-7.56A5.2 5.2 0 0 0 7.6 7.3 4.2 4.2 0 0 0 7 15.5z"/>';
16	const ICO: Record<EnvIcon | 'off', string> = {
17	  'clear-d': '<circle cx="12" cy="12" r="4"/><path d="M12 2.8v2.4M12 18.8v2.4M2.8 12h2.4M18.8 12h2.4M5.5 5.5l1.7 1.7M16.8 16.8l1.7 1.7M5.5 18.5l1.7-1.7M16.8 7.2l1.7-1.7"/>',
18	  'clear-n': '<path d="M19.5 14.2A8 8 0 0 1 9.8 4.5a8 8 0 1 0 9.7 9.7z"/><path d="M17 4.2v2.6M15.7 5.5h2.6"/>',
19	  'cloudy-d': '<path d="M8.2 6.2l-.9-1.5M12.5 5V3.2M16 6.5l1.2-1.3M9 10.2a4 4 0 0 1 7.3-.6"/><path d="M7 19.5h10a3.6 3.6 0 0 0 .5-7.16A5 5 0 0 0 7.9 11.6 4 4 0 0 0 7 19.5z"/>',
20	  'cloudy-n': '<path d="M18.8 8.4a4.6 4.6 0 0 1-5.4-5.6 4.6 4.6 0 0 0-2.2 6.3"/><path d="M7 19.5h10a3.6 3.6 0 0 0 .5-7.16A5 5 0 0 0 7.9 11.6 4 4 0 0 0 7 19.5z"/>',
21	  cloud: '<path d="M7 18h10a3.8 3.8 0 0 0 .5-7.56A5.2 5.2 0 0 0 7.6 9.8 4.2 4.2 0 0 0 7 18z"/>',
22	  rain: RAIN_CLOUD + '<path d="M8.5 18.2l-.9 2.4M12.4 18.2l-.9 2.4M16.3 18.2l-.9 2.4"/>',
23	  fog: '<path d="M7 12.5h10a3.8 3.8 0 0 0 .5-7.56A5.2 5.2 0 0 0 7.6 4.3 4.2 4.2 0 0 0 7 12.5z"/><path d="M4 16h16M6 19.5h12"/>',
24	  storm: RAIN_CLOUD + '<path d="M12.6 16.6l-2 3h3l-2 3"/>',
25	  snow: RAIN_CLOUD + '<path d="M8.5 18.6v.01M12.5 18.6v.01M16.5 18.6v.01M10.5 21.2v.01M14.5 21.2v.01"/>',
26	  off: '<path d="M7 18h10a4 4 0 0 0 .6-7.96A5.5 5.5 0 0 0 7.1 9.2 4.4 4.4 0 0 0 7 18z" opacity=".5"/><path d="M5 4l14 16"/>'
27	};
28	
29	const pad2 = (n: number): string => (n < 10 ? '0' : '') + n;
30	
31	/* opts.nextDelay / opts.skew (D-043): chuyển thẳng cho kho (store.ts EnvDeps), căn nhịp làm mới theo mốc quan trắc và hiệu chỉnh giờ máy lệch */
32	export function setupEnvUI(opts: { live: boolean; nextDelay?: (now: number) => number; skew?: { maxMs: number; stepMs: number } }): EnvUI {
33	  const cfg = CONFIG.env;
34	  let nowFn: () => number = () => Date.now();   // nguồn giờ của đồng hồ / buổi / trạng thái; test ép bằng setNow
35	  let storage: Storage | null = null;
36	  try { storage = window.localStorage; } catch { /* bộ nhớ trình duyệt bị chặn */ }
37	  const store = createEnvStore({
38	    cfg, live: opts.live,
39	    fetch: (u, i) => fetch(u, i),
40	    now: () => nowFn(),   // cùng nguồn giờ với đồng hồ để trạng thái 'stale' khớp giờ đang hiện
41	    storage,
42	    setTimer: (fn, ms) => window.setTimeout(fn, ms),
43	    clearTimer: (id) => window.clearTimeout(id as number),
44	    nextDelay: opts.nextDelay, skew: opts.skew
45	  });
46	  const nowC = () => nowFn() + store.skew();   // giờ hiển thị / mặt trời: đã hiệu chỉnh khi giờ máy lệch
47	
48	  const root = document.getElementById('env');
49	  if (!root) { store.start(); return { store, render() {}, setNow(fn) { nowFn = fn || (() => Date.now()); }, now: nowC }; }
50	  const q = <T extends Element = HTMLElement>(sel: string): T => root.querySelector<T>(sel);
51	  const qa = (sel: string): HTMLElement[] => Array.from(root.querySelectorAll<HTMLElement>(sel));
52	  const pill = q<HTMLButtonElement>('#envPill'), btnX = q<HTMLButtonElement>('#envX'), scrim = q('#envScrim');
53	  const hmEls = qa('[data-hm]'), ssEls = qa('[data-ss]'), icoEls = qa('[data-ico]'), swaps = qa('.env-swap');
54	  const el = {
55	    temp: q('[data-temp]'), tempN: q('[data-temp-n]'), descShort: q('[data-desc-short]'), desc: q('[data-desc]'), feels: q('[data-feels]'),
56	    date: q('[data-date]'), sunDot: q('[data-sundot]'), sunrise: q('[data-sunrise]'), sunset: q('[data-sunset]'), sunNote: q('[data-sunnote]'),
57	    hum: q('[data-hum]'), wind: q('[data-wind]'), rain: q('[data-rain]'), dir: q('[data-dir]'), cloud: q('[data-cloud]'), uv: q('[data-uv]'), foot: q('[data-foot]')
58	  };
59	  const dirArrow = el.dir.querySelector<SVGElement>('.arrow'), dirText = el.dir.querySelector<HTMLElement>('span');
60	
61	  /* Ghi chỉ khi đổi: đọc textContent / thuộc tính không buộc bố trí lại, ghi thừa thì có */
62	  const setText = (e: Element | null, s: string) => { if (e && e.textContent !== s) e.textContent = s; };
63	  const setData = (e: HTMLElement, k: string, v: string) => { if (e.dataset[k] !== v) e.dataset[k] = v; };
64	  const setStyle = (e: HTMLElement | SVGElement, k: string, v: string) => { if (e.style.getPropertyValue(k) !== v) e.style.setProperty(k, v); };
65	  const valKey = new Map<HTMLElement, string>();
66	  /* Ô số liệu: số + đơn vị nhỏ (<small>) */
67	  const setVal = (e: HTMLElement, main: string, small: string) => {
68	    const k = main + '\u0001' + small;
69	    if (valKey.get(e) === k) return;
70	    valKey.set(e, k);
71	    const nodes: (Node | string)[] = [main];
72	    if (small) { const s = document.createElement('small'); s.textContent = small; nodes.push(s); }
73	    e.replaceChildren(...nodes);
74	  };
75	  let icoKey = '';
76	  const setIcon = (k: EnvIcon | 'off') => { if (k === icoKey) return; icoKey = k; for (const e of icoEls) e.innerHTML = ICO[k]; };
77	
78	  /* Bộ định dạng theo ngôn ngữ (chữ số Latin ở mọi ngôn ngữ), tạo lại khi đổi ngôn ngữ */
79	  let fmtLang = '', fmtDate: Intl.DateTimeFormat, fmtH: (n: number) => string, fmtM: (n: number) => string;
80	  /* style:'unit' ném RangeError ở trình duyệt cũ (Safari < 14.1): lùi về số + 'h' / 'min' */
81	  const unitFmt = (loc: string, unit: string, fb: string) => {
82	    try { const f = new Intl.NumberFormat(loc, { style: 'unit', unit, unitDisplay: 'short' }); return (n: number) => f.format(n); }
83	    catch { return (n: number) => n + ' ' + fb; }
84	  };
85	  const fmts = () => {
86	    const lang = getLang();
87	    if (lang === fmtLang) return;
88	    fmtLang = lang;
89	    const loc = lang + '-u-nu-latn';
90	    fmtDate = new Intl.DateTimeFormat(loc, { timeZone: cfg.tz, weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
91	    fmtH = unitFmt(loc, 'hour', 'h');
92	    fmtM = unitFmt(loc, 'minute', 'min');
93	  };
94	  const dur = (min: number): string => { const h = Math.floor(min / 60), m = min % 60; return (h ? fmtH(h) + ' ' : '') + fmtM(m); };
95	  const setAria = (e: HTMLElement, s: string) => { if (e.getAttribute('aria-label') !== s) e.setAttribute('aria-label', s); };
96	
97	  /* ----- Vẽ mọi thứ trừ chữ số đồng hồ (gọi khi phút đổi, số liệu / trạng thái đổi, đổi ngôn ngữ) ----- */
98	  const paint = () => {
99	    fmts();
100	    const now = nowC(), c = envClockParts(new Date(now), cfg.tz), min = c.min;
101	    const data = store.data, st = store.status();
102	    const sr = data && data.sunrise != null ? data.sunrise : cfg.sunFallback[0];
103	    const ss = data && data.sunset != null ? data.sunset : cfg.sunFallback[1];
104	    const day = min >= sr && min < ss;   // ngày / đêm theo đồng hồ, không theo is_day của số liệu (số liệu có thể cũ)
105	    setData(root, 'phase', envPhase(min, sr, ss, cfg.dawnMin, cfg.duskMin));
106	    setData(root, 'state', st);
107	    setText(el.date, fmtDate.format(new Date(now)));
108	    // Vạch mặt trời: chấm ẩn khi ngoài khoảng mọc → lặn
109	    setStyle(el.sunDot, 'inset-inline-start', (Math.max(0, Math.min(1, (min - sr) / (ss - sr))) * 100).toFixed(2) + '%');
110	    setStyle(el.sunDot, 'opacity', day ? '1' : '0');
111	    setText(el.sunrise, t('envSunrise', { t: envHHMM(sr) }));
112	    setText(el.sunset, t('envSunset', { t: envHHMM(ss) }));
113	    setText(el.sunNote, day ? t('envSunLeft', { t: dur(ss - min) }) : t('envSunIn', { t: dur((sr - min + 1440) % 1440) }));
114	    // Chân thẻ
115	    setText(el.foot, st === 'loading' ? t('envLoading')
116	      : st === 'offline' ? t('envOffline')
117	      : st === 'stale' ? t('envStale', { t: envHHMM(data.obsMin) })
118	      : t('envObs', { t: envHHMM(data.obsMin), n: Math.round(cfg.refreshMs / 60000) }));
119	    el.foot.classList.toggle('warn', st === 'stale' || st === 'offline');
120	    // Nhãn đọc màn hình của chỉ báo: kèm nhiệt độ + giờ (vẽ lại mỗi phút; đổi ngôn ngữ: i18n ghi data-i18n-aria trước rồi mới gọi listener nên nhãn này thắng)
121	    setAria(pill, t('envAria') + ': ' + (data ? Math.round(data.temp) + '°, ' : st === 'offline' ? t('envOffline') + ', ' : '') + envHHMM(min));
122	    const dash = '—';
123	    if (!data) {
124	      if (st === 'offline') {
125	        setIcon('off');
126	        setText(el.temp, '– –'); setText(el.tempN, '– –');
127	        setText(el.desc, t('envNoData')); setText(el.descShort, t('envOffline')); setText(el.feels, t('envClockOk'));
128	        for (const e of [el.hum, el.wind, el.rain, el.cloud, el.uv]) setVal(e, dash, '');
129	        setStyle(dirArrow, 'display', 'none'); setText(dirText, dash);
130	      } else {
131	        // Đang tải: chữ giữ chỗ cho khối xám (.v trong suốt), không phải số liệu
132	        setIcon(day ? 'clear-d' : 'clear-n');
133	        setText(el.temp, '00°'); setText(el.tempN, '00');
134	        setText(el.desc, t('envWxPartly')); setText(el.descShort, t('envLoading')); setText(el.feels, t('envFeels', { t: '00' }));
135	        for (const e of [el.hum, el.cloud]) setVal(e, '00', '%');
136	        setVal(el.wind, '00', t('drSpeedUnit')); setVal(el.rain, '0,0', 'mm'); setVal(el.uv, '0', '');
137	        setStyle(dirArrow, 'display', ''); setText(dirText, t('envDirN'));
138	      }
139	      return;
140	    }
141	    const wx = envWx(data.code, day);
142	    setIcon(wx.icon);
143	    const temp = String(Math.round(data.temp));
144	    setText(el.temp, temp + '°'); setText(el.tempN, temp);
145	    setText(el.desc, t(wx.key)); setText(el.descShort, t(wx.key));
146	    setText(el.feels, t('envFeels', { t: Math.round(data.feels) }));
147	    setVal(el.hum, String(Math.round(data.hum)), '%');
148	    setVal(el.wind, String(Math.round(data.wind)), t('drSpeedUnit'));
149	    setVal(el.rain, data.rain.toLocaleString(fmtLang + '-u-nu-latn', { minimumFractionDigits: 1, maximumFractionDigits: 1 }), 'mm');
150	    setStyle(dirArrow, 'display', '');
151	    setStyle(dirArrow, 'transform', 'rotate(' + Math.round(data.dir + 180) + 'deg)');   // mũi tên chỉ hướng gió thổi tới
152	    setText(dirText, t('envDir' + envCompass(data.dir)));
153	    setVal(el.cloud, String(Math.round(data.cloud)), '%');
154	    if (data.uv == null) setVal(el.uv, dash, '');
155	    else {
156	      const uv = day ? Math.round(data.uv) : 0;   // đêm theo đồng hồ: 0, không mức
157	      const lv = envUvLevel(uv);
158	      setVal(el.uv, String(uv), lv ? t('envUv' + lv) : '');
159	    }
160	  };
161	
162	  /* ----- Đồng hồ: căn mép giây kế tiếp; phút đổi thì vẽ lại phần còn lại ----- */
163	  let lastMin = -1, clockTimer = 0;
164	  const tick = (force: boolean) => {
165	    const c = envClockParts(new Date(nowC()), cfg.tz);
166	    const hm = envHHMM(c.min), s = pad2(c.s);
167	    for (const e of hmEls) setText(e, hm);
168	    for (const e of ssEls) setText(e, s);
169	    if (force || c.min !== lastMin) { lastMin = c.min; if (!swapTimer) paint(); }
170	  };
171	  const schedule = () => {
172	    window.clearTimeout(clockTimer);
173	    clockTimer = window.setTimeout(() => { tick(false); schedule(); }, 1000 - (Date.now() % 1000) + 5);   // +5 ms: chắc chắn đã qua mép giây
174	  };
175	
176	  /* ----- Số liệu đổi: nhiệt độ và lưới số mờ ra / vào 180 ms (bỏ khi giảm chuyển động) ----- */
177	  const reduced = window.matchMedia('(prefers-reduced-motion: reduce)');
178	  let swapTimer = 0, shownData = store.data;
179	  const onStore = () => {
180	    const changed = store.data !== shownData;
181	    shownData = store.data;
182	    if (!changed || reduced.matches) { if (!swapTimer) paint(); return; }
183	    if (swapTimer) return;   // đang mờ ra: lúc hiện lại vẽ số liệu mới nhất
184	    for (const e of swaps) e.classList.add('out');
185	    swapTimer = window.setTimeout(() => { swapTimer = 0; paint(); for (const e of swaps) e.classList.remove('out'); }, 180);
186	  };
187	  store.onChange(onStore);
188	  onLangChange(() => tick(true));
189	
190	  /* ----- Mở / đóng (tờ 'env'); khám phá: bỏ focus để Space / mũi tên không bấm lại nút ----- */
191	  const blurInExplore = () => { const a = document.activeElement as HTMLElement | null; if (a && root.contains(a) && document.body.classList.contains('explore')) a.blur(); };
192	  pill.addEventListener('click', () => { openSheet(ui.sheet === 'env' ? 'none' : 'env'); blurInExplore(); });
193	  btnX.addEventListener('click', () => { openSheet('none'); blurInExplore(); });
194	  scrim.addEventListener('pointerdown', (e) => { e.preventDefault(); openSheet('none'); });
195	
196	  /* ----- Ô tô / xe máy trên cảm ứng: chỉ báo đứng dưới chú thích bản đồ nhỏ (#drMapNote). Chiều cao bản đồ (--dr-map-h) chỉ đặt trên #drHud, chú thích
197	     xuống dòng theo ngôn ngữ, nên đo đáy chú thích khi nó đổi cỡ (hiện ra, đổi ngôn ngữ, xoay máy) hoặc bản đồ đổi cỡ, ghi --env-dr-top cho CSS ----- */
198	  const note = document.getElementById('drMapNote'), drHud = document.getElementById('drHud');
199	  if (note && drHud && typeof ResizeObserver !== 'undefined') {
200	    // Ghi trên <html> (không phải #env): #exMpNotice / #exMpIdle nằm ngoài #env cũng đọc được để đứng dưới chỉ báo
201	    const syncDr = () => {
202	      const b = note.getBoundingClientRect();
203	      if (b.height > 0) setStyle(document.documentElement, '--env-dr-top', Math.round(b.bottom + cfg.driveGap) + 'px');
204	    };
205	    new ResizeObserver(syncDr).observe(note);
206	    new MutationObserver(syncDr).observe(drHud, { attributes: true, attributeFilter: ['style'] });
207	    // Xoay máy / đổi cỡ cửa sổ: chú thích có thể đổi chỗ mà không đổi cỡ; đo lại sau khung kế (gộp nhiều sự kiện)
208	    let syncRaf = 0;
209	    const syncSoon = () => { if (syncRaf) return; syncRaf = requestAnimationFrame(() => { syncRaf = 0; syncDr(); }); };
210	    window.addEventListener('resize', syncSoon);
211	    window.addEventListener('orientationchange', syncSoon);
212	  }
213	
214	  /* ----- Khám phá: tờ 'env' đóng bằng đường nào (Esc, bấm cảnh, đổi chế độ) mà focus còn trong #env (vd. liên kết Open-Meteo) thì bỏ focus:
215	     openSheet() trả focus về chỉ báo, còn Space / mũi tên phải lái xe / dù ----- */
216	  new MutationObserver(() => { if (!document.body.classList.contains('sheet-env')) blurInExplore(); }).observe(document.body, { attributes: true, attributeFilter: ['class'] });
217	
218	  /* ----- Tab ẩn: dừng đồng hồ và nhịp lấy số liệu; hiện lại: chạy tiếp (store tự lấy nếu đã quá hạn) ----- */
219	  document.addEventListener('visibilitychange', () => {
220	    const vis = !document.hidden;
221	    store.setVisible(vis);
222	    if (vis) { tick(true); schedule(); } else window.clearTimeout(clockTimer);
223	  });
224	  window.addEventListener('online', () => { void store.refresh(); });
225	
226	  if (document.hidden) store.setVisible(false);
227	  tick(true);
228	  store.start();
229	  if (!document.hidden) schedule();
230	
231	  return {
232	    store,
233	    render: () => tick(true),
234	    setNow(fn: (() => number) | null) { nowFn = fn || (() => Date.now()); tick(true); },
235	    now: nowC
236	  };
237	}
