121	    setAria(pill, t('envAria') + ': ' + (data ? Math.round(data.temp) + '°, ' : st === 'offline' ? t('envOffline') + ', ' : '') + envHHMM(min));
122	    const dash = '—';
123	    if (!data) {
124	      if (st === 'offline') {
125	        setIcon('off');
126	        setText(el.temp, '– –'); setText(el.tempN, '– –');
127	        setText(el.desc, t('envNoData')); setText(el.descShort, t('envOffline')); setText(el.feels, t('envClockOk'));
128	        for (const e of [el.hum, el.wind, el.rain, el.cloud, el.uv]) setVal(e, dash, '');
129	        setStyle(dirArrow, 'display', 'none'); setText(dirText, dash);
130	      } else {
131	        // Đang tải: chữ giữ chỗ cho khối xám (.v trong suốt), không phải số liệu
132	        setIcon(day ? 'clear-d' : 'clear-n');
133	        setText(el.temp, '00°'); setText(el.tempN, '00');
134	        setText(el.desc, t('envWxPartly')); setText(el.descShort, t('envLoading')); setText(el.feels, t('envFeels', { t: '00' }));
135	        for (const e of [el.hum, el.cloud]) setVal(e, '00', '%');
136	        setVal(el.wind, '00', t('drSpeedUnit')); setVal(el.rain, '0,0', 'mm'); setVal(el.uv, '0', '');
137	        setStyle(dirArrow, 'display', ''); setText(dirText, t('envDirN'));
138	      }
139	      return;
140	    }
141	    const wx = envWx(data.code, day);
142	    setIcon(wx.icon);
143	    const temp = String(Math.round(data.temp));
144	    setText(el.temp, temp + '°'); setText(el.tempN, temp);
145	    setText(el.desc, t(wx.key)); setText(el.descShort, t(wx.key));
146	    setText(el.feels, t('envFeels', { t: Math.round(data.feels) }));
147	    setVal(el.hum, String(Math.round(data.hum)), '%');
148	    setVal(el.wind, String(Math.round(data.wind)), t('drSpeedUnit'));
149	    setVal(el.rain, data.rain.toLocaleString(fmtLang + '-u-nu-latn', { minimumFractionDigits: 1, maximumFractionDigits: 1 }), 'mm');
150	    setStyle(dirArrow, 'display', '');
151	    setStyle(dirArrow, 'transform', 'rotate(' + Math.round(data.dir + 180) + 'deg)');   // mũi tên chỉ hướng gió thổi tới
152	    setText(dirText, t('envDir' + envCompass(data.dir)));
153	    setVal(el.cloud, String(Math.round(data.cloud)), '%');
154	    if (data.uv == null) setVal(el.uv, dash, '');
155	    else {
156	      const uv = day ? Math.round(data.uv) : 0;   // đêm theo đồng hồ: 0, không mức
157	      const lv = envUvLevel(uv);
158	      setVal(el.uv, String(uv), lv ? t('envUv' + lv) : '');
159	    }
160	  };
161	
162	  /* ----- Đồng hồ: căn mép giây kế tiếp; phút đổi thì vẽ lại phần còn lại ----- */
163	  let lastMin = -1, clockTimer = 0;
164	  const tick = (force: boolean) => {
165	    const c = envClockParts(new Date(nowC()), cfg.tz);
166	    const hm = envHHMM(c.min), s = pad2(c.s);
167	    for (const e of hmEls) setText(e, hm);
168	    for (const e of ssEls) setText(e, s);
169	    if (force || c.min !== lastMin) { lastMin = c.min; if (!swapTimer) paint(); }
170	  };
171	  const schedule = () => {
172	    window.clearTimeout(clockTimer);
173	    clockTimer = window.setTimeout(() => { tick(false); schedule(); }, 1000 - (Date.now() % 1000) + 5);   // +5 ms: chắc chắn đã qua mép giây
174	  };
175	
176	  /* ----- Số liệu đổi: nhiệt độ và lưới số mờ ra / vào 180 ms (bỏ khi giảm chuyển động) ----- */
177	  const reduced = window.matchMedia('(prefers-reduced-motion: reduce)');
178	  let swapTimer = 0, shownData = store.data;
179	  const onStore = () => {
180	    const changed = store.data !== shownData;
181	    shownData = store.data;
182	    if (!changed || reduced.matches) { if (!swapTimer) paint(); return; }
183	    if (swapTimer) return;   // đang mờ ra: lúc hiện lại vẽ số liệu mới nhất
184	    for (const e of swaps) e.classList.add('out');
185	    swapTimer = window.setTimeout(() => { swapTimer = 0; paint(); for (const e of swaps) e.classList.remove('out'); }, 180);
186	  };
187	  store.onChange(onStore);
188	  onLangChange(() => tick(true));
189	
190	  /* ----- Mở / đóng (tờ 'env'); khám phá: bỏ focus để Space / mũi tên không bấm lại nút ----- */
191	  const blurInExplore = () => { const a = document.activeElement as HTMLElement | null; if (a && root.contains(a) && document.body.classList.contains('explore')) a.blur(); };
192	  pill.addEventListener('click', () => { openSheet(ui.sheet === 'env' ? 'none' : 'env'); blurInExplore(); });
193	  btnX.addEventListener('click', () => { openSheet('none'); blurInExplore(); });
194	  scrim.addEventListener('pointerdown', (e) => { e.preventDefault(); openSheet('none'); });
195	
196	  /* ----- Ô tô / xe máy trên cảm ứng: chỉ báo đứng dưới chú thích bản đồ nhỏ (#drMapNote). Chiều cao bản đồ (--dr-map-h) chỉ đặt trên #drHud, chú thích
197	     xuống dòng theo ngôn ngữ, nên đo đáy chú thích khi nó đổi cỡ (hiện ra, đổi ngôn ngữ, xoay máy) hoặc bản đồ đổi cỡ, ghi --env-dr-top cho CSS ----- */
198	  const note = document.getElementById('drMapNote'), drHud = document.getElementById('drHud');
199	  if (note && drHud && typeof ResizeObserver !== 'undefined') {
200	    // Ghi trên <html> (không phải #env): #exMpNotice / #exMpIdle nằm ngoài #env cũng đọc được để đứng dưới chỉ báo
201	    const syncDr = () => {
202	      const b = note.getBoundingClientRect();
203	      if (b.height > 0) setStyle(document.documentElement, '--env-dr-top', Math.round(b.bottom + cfg.driveGap) + 'px');
204	    };
205	    new ResizeObserver(syncDr).observe(note);
206	    new MutationObserver(syncDr).observe(drHud, { attributes: true, attributeFilter: ['style'] });
207	    // Xoay máy / đổi cỡ cửa sổ: chú thích có thể đổi chỗ mà không đổi cỡ; đo lại sau khung kế (gộp nhiều sự kiện)
208	    let syncRaf = 0;
209	    const syncSoon = () => { if (syncRaf) return; syncRaf = requestAnimationFrame(() => { syncRaf = 0; syncDr(); }); };
210	    window.addEventListener('resize', syncSoon);
211	    window.addEventListener('orientationchange', syncSoon);
212	  }
213	
214	  /* ----- Khám phá: tờ 'env' đóng bằng đường nào (Esc, bấm cảnh, đổi chế độ) mà focus còn trong #env (vd. liên kết Open-Meteo) thì bỏ focus:
215	     openSheet() trả focus về chỉ báo, còn Space / mũi tên phải lái xe / dù ----- */
216	  new MutationObserver(() => { if (!document.body.classList.contains('sheet-env')) blurInExplore(); }).observe(document.body, { attributes: true, attributeFilter: ['class'] });
217	
218	  /* ----- Tab ẩn: dừng đồng hồ và nhịp lấy số liệu; hiện lại: chạy tiếp (store tự lấy nếu đã quá hạn) ----- */
219	  document.addEventListener('visibilitychange', () => {
220	    const vis = !document.hidden;
221	    store.setVisible(vis);
222	    if (vis) { tick(true); schedule(); } else window.clearTimeout(clockTimer);
223	  });
224	  window.addEventListener('online', () => { void store.refresh(); });
225	
226	  if (document.hidden) store.setVisible(false);
227	  tick(true);
228	  store.start();
229	  if (!document.hidden) schedule();
230	
231	  return {
232	    store,
233	    render: () => tick(true),
234	    setNow(fn: (() => number) | null) { nowFn = fn || (() => Date.now()); tick(true); },
235	    now: nowC
236	  };
237	}
