54	  document.querySelectorAll<HTMLElement>('[data-bridge]').forEach((b) => b.addEventListener('click', () => selectBridge(b.dataset.bridge as BridgeKey, true)));
55	  tourHooks.bridge = (k) => selectBridge(k, false);   // Tour 4 cầu: đổi bảng Thông số theo cầu đang thuyết minh, không bay camera
