1	import type * as THREE from 'three';
2	import { CONFIG } from '../../config';
3	import { weatherU, weatherFx } from '../../core/shared';
4	import { water } from '../../core/water';
5	import { hrInside } from '../../bridges/han-tunnel/profile';
6	import { bridgeImpacts, windAt, beaufort } from './impact';
7	import { applyAtmosphere, buildAtmosphere } from './atmosphere';
8	import { buildRain, updateRain, type Rain } from './rain';
9	import { applyWetness, buildWetness, wetMaterials } from './wetness';
10	import { buildWind, updateWind, swayNow } from './wind';
11	import { buildLightning, updateLightning, type Lightning } from './lightning';
12	import { attachSwing, updateHooks } from './effectsHooks';
13	import { buildSummer, updateSummer } from './summer';
14	import { buildFallen, fellTrees, standTrees, updateFallen, fallenState, fallenSnapshot } from './fallen';
15	import { createScenario, type Scenario } from './scenario';
16	import { updateWeatherSound } from './sound';
17	import { controls } from '../../core/renderer';
18	import { createWeatherState, setPreset, presetTarget, stepWeather, windNow, type PresetName, type WeatherParams, type WeatherState } from './state';
19	
20	/* ===== [weather] Thời tiết — Giai đoạn 7: khí quyển + mưa + mặt ướt + gió + bão (chớp, đóng cầu, khoá quay, dừng trình diễn) + kịch bản bão + nắng hè (ảo ảnh, võng cáp) + cây đổ sau bão + âm thanh =====
21	   Giữ trạng thái (current/target/wet), nhận preset, ghi weatherU, điều biến khí quyển (atmosphere.ts), mưa (rain.ts, +1 draw call khi mưa),
22	   mặt ướt (wetness.ts + option `weather` của bridgePatch), gió (wind.ts + option `sway` của bridgePatch, 0 draw call),
23	   chớp (lightning.ts, +1 draw call lúc nháy), vận hành (effectsHooks.ts: weatherFx cho xe, thuyền, trình diễn, cầu quay, quảng cáo). Preset `now` là no-op, 0 draw call mới.
24	   Gọi buildWeather() SAU buildRiverfront() (sau mọi rand()); updateWeather() ngay sau applyNight() trong animate(). */
25	export interface Weather {
26	  state: WeatherState; enabled: boolean; rain: Rain; lightning: Lightning;
27	  scenario: Scenario;                                                  // kịch bản bão (UI gắn on.caption; camera chế độ 'storm' đọc pose())
28	  fallen: { state: typeof fallenState; fell: () => void; stand: () => void; snapshot: typeof fallenSnapshot };   // cây đổ sau bão (API test): fell() đổ ngay quanh điểm nhìn, stand() dựng lại, snapshot() = ma trận thân/tán
29	  attachSwing: typeof attachSwing;                                     // gán predicate khoá quay cho SwingController (main.ts)
30	  fx: () => typeof weatherFx;                                          // hệ số vận hành đang áp (xe, thuyền, trình diễn, cầu quay) — cho test
31	  setPreset: (name: PresetName) => void; setIntensity: (k: number) => void;
32	  setRainCount: (n: number) => void; wetMaterials: () => THREE.MeshStandardMaterial[];
33	  impact: () => ReturnType<typeof bridgeImpacts>;
34	  windAt: (z: number) => number; beaufort: (v?: number) => number;
35	  setParams: (p: Partial<WeatherParams>, instant?: boolean) => void;   // ghi đè target (test / kịch bản); instant: gán luôn current
36	  sway: () => ReturnType<typeof swayNow>;                              // biên độ lắc đang hiển thị (m, đã phóng đại)
37	  /* Chế độ Trực tiếp (D-043, realtime/liveEnv.ts). p: đích từ số liệu thật (envMap.ts), tiến dần theo tau × CONFIG.live.tauScale; không đụng state.preset / intensity
38	     (lựa chọn mô phỏng được giữ nguyên để trả lại). instant: gán luôn current + mặt ướt (ảnh chụp đầu tiên của phiên).
39	     null: rời Trực tiếp — tauScale 1, đích về preset mô phỏng đã nhớ, enabled như setPreset (preset `now` ⇒ tắt, no-op). */
40	  setLive: (p: WeatherParams | null, instant?: boolean) => void;
41	  readonly live: boolean;
42	  stopScenario: () => void;                                            // dừng kịch bản bão, không trả preset cũ (như người xem tự chọn preset)
43	  standTrees: () => void;                                              // dựng lại cây đổ sau bão
44	}
45	let current: Weather | null = null;
46	let live = false;   // chế độ Trực tiếp đang lái thời tiết (setLive)
47	export const getWeather = () => current;
48	
49	export function buildWeather(): Weather {
50	  const state = createWeatherState();
51	  buildAtmosphere();                       // chụp giá trị gốc (sương, Sky, nước, mây) trước khi áp thời tiết
52	  buildWetness();                          // đăng ký đường chung; đường các cầu đã registerWet() trong materials.ts của cầu
53	  const rain = buildRain();                // mesh mưa ẩn, program biên dịch sẵn
54	  buildSummer();                           // vá shader đường (ảo ảnh); võng cáp qua option `sag` của bridgePatch
55	  buildFallen();                           // quét cặp thân–tán cây (sau mọi lệnh dựng và dọn cây)
56	  buildWind();                            // vá shader tán cây; dây đã có option `sway` trong materials.ts của cầu
57	  const lightning = buildLightning();      // mesh tia chớp ẩn, program biên dịch sẵn
58	  current = {
59	    state, enabled: CONFIG.weather.enabled, rain, lightning, attachSwing, fx: () => weatherFx,
60	    scenario: createScenario(state, (on) => { current.enabled = on; }, standTrees),
61	    fallen: { state: fallenState, fell: () => fellTrees(controls.target, state.current.windDir), stand: standTrees, snapshot: fallenSnapshot },
62	    setPreset(name) { setWeatherPreset(name); },
63	    setIntensity(k) { setWeatherIntensity(k); },
64	    setRainCount: (n: number) => rain.setCount(n),
65	    wetMaterials,
66	    impact: () => bridgeImpacts(state.current),
67	    windAt: (z: number) => windAt(z, state.current.wind),
68	    beaufort: (v?: number) => beaufort(v ?? state.current.wind),
69	    setParams(p, instant = false) { Object.assign(state.target, p); if (instant) Object.assign(state.current, p); current.enabled = true; },
70	    sway: swayNow,
71	    setLive(p, instant = false) {
72	      if (p) {
73	        live = true; state.tauScale = CONFIG.live.tauScale;
74	        state.target = { ...p };
75	        if (instant) { Object.assign(state.current, p); state.wet = p.rain; }
76	        current.enabled = true;
77	      } else {
78	        if (!live) return;
79	        live = false; state.tauScale = 1;
80	        state.target = presetTarget(state.preset, state.intensity);
81	        current.enabled = state.preset !== 'now';
82	      }
83	    },
84	    get live() { return live; },
85	    stopScenario: () => current.scenario.stop(false),
86	    standTrees
87	  };
88	  return current;
89	}
90	
91	export function setWeatherPreset(name: PresetName) {
92	  if (!current) return;
93	  current.scenario.stop(false);            // người xem tự chọn: kịch bản dừng, không trả preset cũ
94	  if (name !== 'now') standTrees();         // rời trạng thái "sau bão"
95	  setPreset(current.state, name);
96	  current.enabled = name !== 'now';
97	}
98	export function setWeatherIntensity(k: number) {
99	  if (!current) return;
100	  current.scenario.stop(false);
101	  setPreset(current.state, current.state.preset, k);
102	}
103	
104	export function updateWeather(dt: number, time: number, night: number, cam: THREE.Camera) {
105	  if (!current) return;
106	  const s = current.state;
107	  current.scenario.update(dt);
108	  stepWeather(s, dt);
109	  applyAtmosphere(s, night, dt, live);
110	  const c = s.current, w = windNow(c, time), wet = s.wet < 1e-3 ? 0 : s.wet;   // dưới ngưỡng: 0 chính xác để nhánh shader ướt không chạy
111	  applyWetness(wet);
112	  updateWind(c, w, current.enabled);       // lắc dây/cây, thuyền, lửa, sóng (0 draw call)
113	  const p = cam.position, blocked = hrInside(p.x, p.y, p.z) || p.y < water.position.y;   // camera trong hầm / dưới mặt nước
114	  updateRain(dt, c.rain < 1e-3 ? 0 : c.rain, w, c.windDir, blocked);   // tắt mưa trong hầm / dưới mặt nước
115	  updateLightning(dt, c.lightning, blocked);                          // sau applyAtmosphere: cộng xung hemi / exposure
116	  updateSummer(c, current.enabled);                                   // võng cáp phóng đại khi nóng
117	  aftermath(s, dt);                                                   // bão qua đỉnh rồi lặng: cây đổ
118	  updateFallen(dt);
119	  updateWeatherSound(dt, c, w, blocked, current.lightning);           // mưa, gió, sấm (Web Audio, chỉ khi người xem bật âm thanh)
120	  updateHooks(c, dt);                                                // đóng cầu, khoá quay, dừng trình diễn, thuyền về bến, quảng cáo
121	  weatherU.uWet.value = wet; weatherU.uRain.value = c.rain; weatherU.uWind.value = c.wind; weatherU.uGust.value = Math.max(0, w - c.wind);
122	  weatherU.uHaze.value = c.haze; weatherU.uSwayK.value = current.enabled ? CONFIG.weather.swayExaggeration : 0;
123	}
124	
125	/* Sau bão (mục 4.8): gió hiện tại từng đạt armWind rồi gió đích xuống dưới calmWind (và hết cấm) → cây đổ quanh điểm nhìn.
126	   Đang chạy kịch bản: đổ quanh điểm nhìn của mốc đang chạy (camera lúc đó còn đang bay tới). Rời trạng thái: hết `hold` giây, gió đích lại tăng, chọn preset khác 'now', hoặc kịch bản kết thúc/dừng. Chưa từng có bão thì không đụng cây. */
127	let armed = false, afterT = -1;
128	function aftermath(s: WeatherState, dt: number) {
129	  const F = CONFIG.weather.fallen, sc = current.scenario;
130	  if (s.current.wind >= F.armWind) armed = true;
131	  if (live) { armed = false; if (afterT >= 0) { standTrees(); afterT = -1; } return; }   // Trực tiếp: không hư hại theo số liệu thật (spec §1), không mang "đã có bão" sang Mô phỏng
132	  if (armed && s.target.wind <= F.calmWind && !s.target.closed) { armed = false; fellTrees(sc.running ? sc.focus() : controls.target, s.current.windDir); afterT = 0; }
133	  if (afterT >= 0) {
134	    afterT += dt;
135	    if (afterT > F.hold || s.target.wind > F.calmWind) { standTrees(); afterT = -1; }
136	  }
137	}
