body.compact.sheet-env #envScrim{opacity:1;pointer-events:auto;}
/* ===== Chế độ Trực tiếp / Mô phỏng (D-043, ui/liveUI.ts) =====
   Phần tử mang `hidden` cho tới khi có bộ điều khiển (liveEnv null ⇒ không hiện gì). Quy tắc chung dưới đây đặt display nhưng [hidden] (!important) vẫn thắng.
   Chỉ báo: chấm (đỏ nhịp nhẹ = Trực tiếp, xám = Mô phỏng) + chữ chế độ. Chữ chỉ ở tham quan, cửa sổ > 420 px: khám phá và cửa sổ hẹp chỉ còn chấm (không đổi bố cục chỉ báo ở các chế độ, D-042) */
#envPill .env-mode{display:inline-flex;align-items:center;gap:5px;font:600 9.5px/1 var(--font-mono);letter-spacing:.12em;text-transform:uppercase;color:var(--muted);white-space:nowrap;}
#env .env-mode .dot,#env .env-sw .dot,.live-lock .dot{width:7px;height:7px;border-radius:50%;background:var(--muted);flex:none;}
#env[data-mode="live"] #envPill .env-mode{color:#f2a49a;}
#env[data-mode="live"] .env-mode .dot,#env .env-sw .dot,.live-lock .dot{background:#ef5a4a;}
#env[data-mode="live"] .env-mode .dot{animation:envLive 2.4s ease-out infinite;}
@keyframes envLive{0%{box-shadow:0 0 0 0 rgba(239,90,74,.55);}70%,100%{box-shadow:0 0 0 5px rgba(239,90,74,0);}}   /* giảm chuyển động: quy tắc chung cuối tệp tắt mọi animation */
body.explore #envPill .env-mode .txt,body.compact.drive #envPill .env-mode .txt{display:none;}
@media (max-width:420px){#envPill .env-mode .txt{display:none;}}
/* Thẻ: công tắc hai chế độ (nhóm radio) + dòng giải thích, trên chân thẻ */
#env .env-modes{margin-top:14px;display:flex;flex-direction:column;gap:7px;}
#env .env-sw{display:flex;gap:3px;padding:3px;border-radius:10px;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.08);}
#env .env-sw button{flex:1 1 0;display:inline-flex;align-items:center;justify-content:center;gap:6px;min-width:0;min-height:34px;margin:0;padding:6px 10px;border:0;border-radius:7px;background:transparent;color:var(--muted);font:500 12.5px/1.2 var(--font-body);cursor:pointer;-webkit-tap-highlight-color:transparent;}
#env .env-sw button[aria-checked="true"]{background:rgba(var(--acc),.2);color:var(--text);box-shadow:inset 0 0 0 1px rgba(var(--acc),.4);}
@media (hover:hover){#env .env-sw button[aria-checked="false"]:hover{background:rgba(255,255,255,.06);color:var(--text);}}
#env .env-sw button:focus-visible{outline:2px solid var(--gold);outline-offset:1px;}
#env .env-mode-note{margin:0;font-size:11px;line-height:1.4;color:var(--muted);}
body.compact #env .env-sw button{min-height:44px;}
/* Bảng Cài đặt: dòng khóa (Trực tiếp) / nút về Trực tiếp (Mô phỏng) trên nhóm Ngày–Đêm + thời tiết */
.live-lock{display:flex;flex-wrap:wrap;align-items:center;gap:6px 8px;padding:7px 9px;border-radius:5px;background:rgba(239,90,74,.08);border:1px solid rgba(239,90,74,.3);font-size:11.5px;line-height:1.3;color:var(--text);}
.live-lock[data-mode="manual"]{padding:0;background:none;border:0;}
.live-lock .live-lock-txt{display:inline-flex;align-items:center;gap:6px;flex:1 1 auto;min-width:0;}
.live-lock button{flex:none;padding:6px 10px;}
#brandBody :is(#btnNight,#btnWxStorm,#timeSlider,#weatherSel,#weatherK):disabled{opacity:.38;cursor:default;}
@media (hover:hover){#brandBody :is(#btnNight,#btnWxStorm):disabled:hover{background:rgba(255,255,255,.04);}}
/* Thông báo: tính năng cần ban đêm đã chuyển sang Mô phỏng; dưới dòng hướng dẫn #hint / #swRideHint và #swStormNote (z-index < 10: tờ mở nằm trên) */
#liveNotice{display:flex;align-items:center;gap:10px;left:50%;transform:translateX(-50%);top:calc(104px + env(safe-area-inset-top,0px));padding-block:7px;padding-inline:14px 8px;font-size:12.5px;line-height:1.35;color:var(--text);max-width:calc(100vw - 24px);box-sizing:border-box;z-index:7;}
#liveNotice button{flex:none;padding:6px 10px;}
body.compact #liveNotice{top:calc(176px + env(safe-area-inset-top,0px));width:max-content;flex-wrap:wrap;justify-content:center;text-align:center;padding-inline:12px;}

