import { serveDir, launch, openApp, frames } from 'file:///D:/2026%20-%20Tuan/danang-vite/.worktrees/thoi-tiet-thuc/tests/lib.mjs';
const OUT = 'C:/Users/Client/AppData/Local/Temp/claude/e6d5994f4eac8fdb/2d68e1be-b891-4f16-ac5e-496937b4951b/scratchpad/shots/';
const srv = await serveDir('D:/2026 - Tuan/danang-vite/.worktrees/thoi-tiet-thuc/dist');
const browser = await launch();
const { page, errors } = await openApp(browser, srv.url + '?envmode=live', { width: 1280, height: 720 });
const U = (h, m) => Date.UTC(2026, 10, 15, h, m);
const W = (o) => ({ obs: 0, obsMin: 600, temp: 27, feels: 29, hum: 70, wind: 12, dir: 45, rain: 0, cloud: 5, uv: 5, code: 0, isDay: true, sunrise: 355, sunset: 1035, gust: 20, vis: 24000, rate: 0, ...o });
const cases = [
  ['1-trua-nang', U(5, 0), W({})],
  ['2-u-am', U(4, 0), W({ code: 3, cloud: 100, hum: 88 })],
  ['3-mua-to-dem', U(13, 0), W({ code: 65, cloud: 100, hum: 98, rate: 15, rain: 3.75, vis: 3000, wind: 30, gust: 50 })],
  ['4-suong', U(0, 30), W({ code: 45, cloud: 100, hum: 99, vis: 300, wind: 4, gust: 6 })],
  ['5-hoang-hon', U(10, 5), W({ cloud: 20 })],
  ['6-chang-vang', U(10, 30), W({ cloud: 20 })],
  ['7-nua-dem-quang', U(17, 0), W({ cloud: 10 })]
];
console.log('mode', await page.evaluate(() => window.__app.live && window.__app.live.mode));
for (const [name, t, wx] of cases) {
  const info = await page.evaluate(async ([t, wx]) => {
