import { serveDir, launch, openApp, frames } from 'file:///D:/2026%20-%20Tuan/danang-vite/.worktrees/thoi-tiet-thuc/tests/lib.mjs';
const OUT = 'C:/Users/Client/AppData/Local/Temp/claude/e6d5994f4eac8fdb/2d68e1be-b891-4f16-ac5e-496937b4951b/scratchpad/shots/ui-';
const srv = await serveDir('D:/2026 - Tuan/danang-vite/.worktrees/thoi-tiet-thuc/dist');
const browser = await launch();
const only = process.argv[2] || '';
const setups = [
  ['pc', { width: 1280, height: 720 }],
  ['ph', { width: 390, height: 844, mobile: true }]
];
const log = (...a) => console.log(...a);
const st = (page) => page.evaluate(() => {
  const a = window.__app, r = (id) => { const e = document.getElementById(id); if (!e) return null; const b = e.getBoundingClientRect(); return e.hidden || !b.width ? 'ẩn' : [Math.round(b.left), Math.round(b.top), Math.round(b.width), Math.round(b.height)].join(','); };
  return { mode: a.live && a.live.mode, envMode: document.getElementById('env').dataset.mode, pill: r('envPill'), modeTxt: document.querySelector('#envMode [data-mode-text]')?.textContent, note: document.getElementById('envModeNote')?.textContent,
    dis: ['timeSlider', 'btnNight', 'weatherSel', 'weatherK', 'btnWxStorm'].map((i) => document.getElementById(i).disabled ? 1 : 0).join(''), notice: r('liveNotice'), target: a.dayNight.target, aria: document.getElementById('envPill').getAttribute('aria-label') };
});
for (const [tag, vp] of setups) for (const lang of ['vi', 'ar']) {
  const key = `${tag}-${lang}`; if (only && !key.includes(only)) continue;
  const { page, errors } = await openApp(browser, srv.url + '?envmode=live#' + lang, vp);
  await page.waitForFunction((l) => document.documentElement.lang === l, lang);
  await page.evaluate(() => window.__app.env.setNow(() => Date.UTC(2026, 10, 15, 5, 0)));
  await frames(page, 3);
  log(key, 'đầu (chưa số liệu)', JSON.stringify(await st(page)));
  await page.screenshot({ path: OUT + key + '-1-pill-live-nodata.png' });
  await page.evaluate(() => { const a = window.__app, t = Date.UTC(2026, 10, 15, 5, 0); a.env.store.inject({ obs: t - 300000, obsMin: 715, temp: 27, feels: 29, hum: 70, wind: 12, dir: 45, rain: 0, cloud: 30, uv: 5, code: 2, isDay: true, sunrise: 355, sunset: 1035, gust: 20, vis: 24000, rate: 0 }); });
  await frames(page, 3);
  await page.evaluate(() => window.__app.ui.openSheet('env')); await page.waitForTimeout(500);
  log(key, 'thẻ live', JSON.stringify(await st(page)));
  await page.screenshot({ path: OUT + key + '-2-card-live.png' });
  await page.evaluate(() => window.__app.ui.openSheet('settings')); await page.waitForTimeout(500);
  await page.screenshot({ path: OUT + key + '-3-settings-live.png' });
  // khóa tầng mã: ép sự kiện lên ô chọn / thanh đã disabled
  const lockOk = await page.evaluate(() => {
    const a = window.__app, sel = document.getElementById('weatherSel'), k = document.getElementById('weatherK'), sl = document.getElementById('timeSlider');
    const before = JSON.stringify([a.weather.state.preset, a.weather.state.intensity, a.dayNight.target]);
    sel.value = 'storm'; sel.dispatchEvent(new Event('change')); k.value = '20'; k.dispatchEvent(new Event('input')); sl.value = '100'; sl.dispatchEvent(new Event('input'));
    document.getElementById('btnNight').dispatchEvent(new MouseEvent('click')); document.getElementById('btnWxStorm').dispatchEvent(new MouseEvent('click'));
    return { same: before === JSON.stringify([a.weather.state.preset, a.weather.state.intensity, a.dayNight.target]), sel: sel.value, k: k.value, sl: sl.value, sc: a.weather.scenario.running };
  });
  log(key, 'khóa mã', JSON.stringify(lockOk));
  // chuyển Mô phỏng bằng nút trong Cài đặt
  await page.click('#btnToManual'); await page.waitForTimeout(300);
  log(key, 'sau btnToManual', JSON.stringify(await st(page)), 'focus', await page.evaluate(() => document.activeElement?.id));
  await page.screenshot({ path: OUT + key + '-4-settings-manual.png' });
  await page.evaluate(() => window.__app.ui.openSheet('env')); await page.waitForTimeout(500);
  await page.screenshot({ path: OUT + key + '-5-card-manual.png' });
  // bàn phím: mũi tên trên nhóm radio
  await page.focus('#envModeManual'); await page.keyboard.press('ArrowRight'); await page.waitForTimeout(100);
  log(key, 'mũi tên →', (await st(page)).mode, 'focus', await page.evaluate(() => document.activeElement?.id));
  await page.keyboard.press('ArrowLeft'); await page.waitForTimeout(100);
  log(key, 'mũi tên ←', (await st(page)).mode);
  await page.focus('#envModeLive'); await page.keyboard.press('Space'); await page.waitForTimeout(100);
  log(key, 'Space trên Trực tiếp', (await st(page)).mode);
  await page.evaluate(() => window.__app.ui.closeSheets()); await page.waitForTimeout(400);
  await page.screenshot({ path: OUT + key + '-6-pill-live.png', clip: { x: 0, y: 0, width: vp.width, height: 120 } });
  // Trình diễn khi Trực tiếp ⇒ Mô phỏng + thông báo
  await page.evaluate(() => { const b = document.getElementById('btnShow'); window.__app.ui.reveal(b); }); await page.waitForTimeout(400);
  await page.click('#btnShow'); await page.waitForTimeout(400);
  await page.evaluate(() => window.__app.ui.closeSheets()); await page.waitForTimeout(400);
  log(key, 'sau Trình diễn', JSON.stringify(await st(page)));
  await page.screenshot({ path: OUT + key + '-7-notice.png' });
  await page.click('#btnNoticeLive'); await page.waitForTimeout(300);
  log(key, 'sau Về Trực tiếp', JSON.stringify(await st(page)));
  // rfHearts khi Trực tiếp
  await page.evaluate(() => { const b = document.querySelector('[data-view="rfHearts"]'); window.__app.ui.reveal(b); b.click(); }); await page.waitForTimeout(300);
  log(key, 'sau rfHearts', JSON.stringify(await st(page)));
  log(key, 'errors', errors);
  await page.close();
}
// khám phá (dù lượn), máy tính: chỉ còn chấm
if (!only || only === 'ex') {
  const { page, errors } = await openApp(browser, srv.url + '?envmode=live&explore=glider', { width: 1280, height: 720 });
  await frames(page, 5);
  log('glider', JSON.stringify(await st(page)));
  await page.screenshot({ path: OUT + 'glider-pc.png', clip: { x: 700, y: 0, width: 580, height: 120 } });
  log('glider errors', errors); await page.close();
  const m = await openApp(browser, srv.url + '?envmode=live&explore=drive', { width: 390, height: 844, mobile: true });
  await frames(m.page, 5);
  log('drive-ph', JSON.stringify(await st(m.page)));
  await m.page.screenshot({ path: OUT + 'drive-ph.png' });
  log('drive errors', m.errors); await m.page.close();
}
await browser.close(); srv.close();

